function add(a,b){ return {re:a.re+b.re, im:a.im+b.im}; }
function sub(a,b){ return {re:a.re-b.re, im:a.im-b.im}; }
function mul(a,b){ return {re:a.re*b.re - a.im*b.im, im:a.re*b.im + a.im*b.re}; }
function div(a,b){ var d=b.re*b.re + b.im*b.im; if(d===0) return {re:NaN, im:NaN}; return {re:(a.re*b.re + a.im*b.im)/d, im:(a.im*b.re - a.re*b.im)/d}; }
function abs(a){ return Math.sqrt(a.re*a.re + a.im*a.im); }
function arg(a){ return Math.atan2(a.im, a.re); }
function conj(a){ return {re:a.re, im:-a.im}; }
function fromPolar(r, th){ return {re:r*Math.cos(th), im:r*Math.sin(th)}; }
function toPolar(a){ return {r:abs(a), th:arg(a)}; }
var EXPORTS={ add:add, sub:sub, mul:mul, div:div, abs:abs, arg:arg, conj:conj, fromPolar:fromPolar, toPolar:toPolar };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ComplexForgePure = EXPORTS; }
